import { Table, useTableController, type Key } from '@tale-ui/react/table';

const people = [
  { id: '1', name: 'Alice', role: 'Designer' },
  { id: '2', name: 'Bob', role: 'Engineer' },
  { id: '3', name: 'Carol', role: 'Engineer' },
  { id: '4', name: 'Dave', role: 'Manager' },
];

export function PeopleTable() {
  const controller = useTableController({
    tableId: 'people',
    defaultSortDescriptor: { column: 'name', direction: 'ascending' },
    defaultSelectedKeys: new Set(['2']),
    defaultFilter: { schemaVersion: '1.0.0', value: 'engineer' },
    defaultPage: 1,
    defaultPageSize: 2,
    totalRows: people.length,
  });
  const filtered = controller.filtering.filterRows(people, (person, filter) =>
    `${person.name} ${person.role}`.toLowerCase().includes(filter.value.toLowerCase()),
  );
  const sorted = controller.sorting.sortRows(filtered, (left, right, column: Key) => {
    if (column === 'role') return left.role.localeCompare(right.role);
    return left.name.localeCompare(right.name);
  });
  const visible = controller.pagination.paginateRows(sorted);

  return (
    <Table.Root
      {...controller.tableProps}
      aria-label="People"
      selectionMode="multiple"
    >
      <Table.Header>
        <Table.Column id="name" isRowHeader allowsSorting>
          Name
        </Table.Column>
        <Table.Column id="role" allowsSorting>
          Role
        </Table.Column>
      </Table.Header>
      <Table.Body items={visible}>
        {(person) => (
          <Table.Row id={person.id}>
            <Table.Cell>{person.name}</Table.Cell>
            <Table.Cell>{person.role}</Table.Cell>
          </Table.Row>
        )}
      </Table.Body>
    </Table.Root>
  );
}
